<?php

declare(strict_types=1);

/**
 * Generate docs/libsql3-cli-reference.md from Symfony Console metadata.
 *
 * D-16: the generated file owns command signatures; docs/libsql3-man.md owns
 * workflows. This script is deterministic so CI can assert zero diff.
 */

use Libsql3\App;
use Libsql3\Internal\PsyCommandAdapter;
use Symfony\Component\Console\Input\InputArgument;
use Symfony\Component\Console\Input\InputOption;

require __DIR__ . '/../vendor/autoload.php';

// App construction validates the endpoint; docs generation does not talk to it.
if (trim((string) (getenv('LIBSQL_API_ENDPOINT') ?: '')) === '') {
    putenv('LIBSQL_API_ENDPOINT=https://example.invalid');
}

function ref_md_cell(string $value): string
{
    return str_replace(['|', "\r", "\n"], ['\\|', '', ' '], $value);
}

function ref_md_default(mixed $default): string
{
    if ($default === null) {
        return '—';
    }
    if (is_bool($default)) {
        return $default ? '`true`' : '`false`';
    }
    if ($default === '') {
        return '`""`';
    }
    if (is_array($default)) {
        return '`' . json_encode($default, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . '`';
    }
    if (is_scalar($default)) {
        return '`' . (string) $default . '`';
    }

    return '—';
}

function ref_md_option_value(InputOption $option): string
{
    if (!$option->acceptValue()) {
        return 'flag';
    }
    if ($option->isValueRequired()) {
        return 'required';
    }

    return 'optional';
}

$app = new App();
$libsqlCommands = $app->getLibsqlCommands();
foreach ($libsqlCommands as $command) {
    $app->add(new PsyCommandAdapter($command));
}

$commands = $app->all();
ksort($commands, SORT_NATURAL);

$lines = [
    '---',
    'layout: manual',
    'title: libsql3 command reference',
    'description: Generated command signatures, arguments, options and defaults for every libsql3 command.',
    'section: CLI',
    'eyebrow: Generated reference',
    'permalink: /cli/reference/',
    '---',
    '',
    '> Generated by `cd libsql3 && composer docs` from Symfony Console metadata.',
    '> Do not edit by hand. CI fails when a signature changes without regeneration.',
    '>',
    '> Narrative workflows, first-run guidance, scheme policy, and exit codes live in',
    '> the libsql3 CLI page in this manual (see the sidebar).',
    '',
    sprintf(
        '%d libsql3 commands and %d total commands (including Symfony Console built-ins).',
        count($libsqlCommands),
        count($commands)
    ),
    '',
    '## Commands',
    '',
];

foreach ($commands as $name => $command) {
    $definition = $command->getNativeDefinition();

    $lines[] = '### `' . $name . '`';
    $lines[] = '';
    $lines[] = ref_md_cell((string) ($command->getDescription() ?: 'No description provided.'));
    $lines[] = '';

    $arguments = $definition->getArguments();
    $lines[] = '#### Arguments';
    $lines[] = '';
    if ($arguments === []) {
        $lines[] = 'None.';
    } else {
        $lines[] = '| Name | Mode | Default | Description |';
        $lines[] = '| ---- | ---- | ------- | ----------- |';
        /** @var InputArgument $argument */
        foreach ($arguments as $argument) {
            $lines[] = sprintf(
                '| `%s` | %s | %s | %s |',
                ref_md_cell($argument->getName()),
                $argument->isRequired() ? 'required' : 'optional',
                ref_md_default($argument->getDefault()),
                ref_md_cell($argument->getDescription())
            );
        }
    }
    $lines[] = '';

    $options = $definition->getOptions();
    $lines[] = '#### Options';
    $lines[] = '';
    if ($options === []) {
        $lines[] = 'None.';
    } else {
        $lines[] = '| Name | Shortcut | Value | Default | Description |';
        $lines[] = '| ---- | -------- | ----- | ------- | ----------- |';
        /** @var InputOption $option */
        foreach ($options as $option) {
            $shortcut = $option->getShortcut();
            $lines[] = sprintf(
                '| `--%s` | %s | %s | %s | %s |',
                ref_md_cell($option->getName()),
                $shortcut === null ? '—' : '`-' . ref_md_cell($shortcut) . '`',
                ref_md_option_value($option),
                ref_md_default($option->getDefault()),
                ref_md_cell($option->getDescription())
            );
        }
    }
    $lines[] = '';
}

$target = dirname(__DIR__, 2) . '/docs/libsql3-cli-reference.md';
if (file_put_contents($target, implode("\n", $lines) . "\n") === false) {
    fwrite(STDERR, "Could not write {$target}\n");
    exit(1);
}

fwrite(STDOUT, basename($target) . " regenerated\n");
